CREATE TABLE tags (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(length(name) BETWEEN 1 AND 60));
CREATE TABLE garment_tags (garment_id INTEGER NOT NULL REFERENCES garments(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(garment_id, tag_id));
CREATE TABLE collections (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(length(name) BETWEEN 1 AND 100), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE collection_items (collection_id INTEGER NOT NULL REFERENCES collections(id) ON DELETE CASCADE, garment_id INTEGER NOT NULL REFERENCES garments(id) ON DELETE CASCADE, PRIMARY KEY(collection_id, garment_id));
